// This file is generated by AI.

// 文件监听的忽略判据: **只排除版本控制元数据目录**。
//
// 应用在项目根上递归挂了三处监听 (`git/status.ts`、`lsp/watch.ts`、`lib/fs.ts` 的
// `watchDirectory`), 而 `git status` 本身就会创建并删除 `.git/index.lock` —— 不跳过 `.git/`,
// 就会形成"git status → 写索引 → 触发监听 → git status"的自激回路, 编辑器不停闪。
//
// `.gitignore` / `.gitattributes` 是正常文件 (默认 `.gitignore` 由应用写入, 也必须被监听到),
// 只有 `.git` 这个**目录**要跳过。

/** 要跳过的目录名 (按小写比较, 兼容 Windows 的大小写不敏感)。 */
const IGNORED_DIRECTORIES = new Set(['.git', '.hg', '.svn']);

/**
 * 这条路径是否落在版本控制元数据里。
 *
 * 按**路径分段**判断而不是 `includes('.git')`: 前者不会误伤 `game/.gitkeep`、
 * `scene/git.txt` 这类正常文件。
 */
export function isIgnoredWatchPath(path: string): boolean {
  if (!path) return false;
  const normalized = path.replace(/\\/g, '/');
  for (const segment of normalized.split('/')) {
    if (IGNORED_DIRECTORIES.has(segment.toLowerCase())) return true;
  }
  return false;
}

/**
 * 一批事件路径里是否**至少有一条值得处理**。
 *
 * 拿不到路径时 (插件的某些事件可能不带 `paths`) 一律当作值得处理 —— 宁可多刷一次,
 * 也不要漏掉真实的文件变更。
 */
export function hasRelevantWatchPath(paths: readonly string[] | undefined | null): boolean {
  if (!paths || paths.length === 0) return true;
  return paths.some((path) => !isIgnoredWatchPath(path));
}
